changeSet.sql:
DELETE FROM shared_facilities
WHERE branch_id IN (
    SELECT id FROM branches
    WHERE is_deleted = true
      AND (creation_status IS NULL OR creation_status <> 'COMPLETED')
);

DELETE FROM rooms
WHERE branch_id IN (
    SELECT id FROM branches
    WHERE is_deleted = true
      AND (creation_status IS NULL OR creation_status <> 'COMPLETED')
);

DELETE FROM branches
WHERE is_deleted = true
  AND (creation_status IS NULL OR creation_status <> 'COMPLETED');
